import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../App';

const navItems = [
  { path: '/dashboard', icon: '⊞', label: 'Dashboard' },
  { path: '/weather', icon: '🌤', label: 'Weather' },
  { path: '/recommendations', icon: '🌱', label: 'Smart Crops' },
  { path: '/disease-scanner', icon: '🔬', label: 'Disease Scan' },
  { path: '/chatbot', icon: '🤖', label: 'KisanGPT' },
];

export default function Sidebar({ open, onClose }) {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, setUser, lang, setLang, LANGS } = useAuth();

  const go = (path) => { navigate(path); onClose?.(); };

  return (
    <>
      {open && <div className="fixed inset-0 bg-black/60 z-30 lg:hidden" onClick={onClose} />}
      <aside className={`fixed top-0 left-0 h-full w-64 z-40 flex flex-col glass-dark border-r border-green-900/40 transition-transform duration-300 ${open ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0`}>
        {/* Logo */}
        <div className="p-6 border-b border-green-900/40">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl btn-primary flex items-center justify-center text-xl ai-glow">🌿</div>
            <div>
              <div className="font-display font-bold text-white text-lg leading-tight">SmartSheti</div>
              <div className="text-green-400 text-xs font-medium tracking-widest">AI PLATFORM</div>
            </div>
          </div>
        </div>

        {/* Nav */}
        <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
          {navItems.map(item => (
            <button key={item.path} onClick={() => go(item.path)}
              className={`sidebar-link w-full flex items-center gap-3 px-4 py-3 rounded-xl text-left text-sm font-medium transition-all ${location.pathname === item.path ? 'active bg-green-500/20 text-green-300 border-l-4 border-green-400' : 'text-gray-400 hover:text-white'}`}>
              <span className="text-lg">{item.icon}</span>
              {item.label}
            </button>
          ))}
        </nav>

        {/* Language */}
        <div className="p-4 border-t border-green-900/40">
          <div className="text-xs text-gray-500 mb-2 uppercase tracking-wider">Language</div>
          <select value={lang} onChange={e => setLang(e.target.value)}
            className="w-full bg-black/30 border border-green-900/40 text-white text-sm rounded-lg px-3 py-2">
            {Object.entries(LANGS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
          </select>
        </div>

        {/* User */}
        <div className="p-4 border-t border-green-900/40">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-full bg-gradient-to-br from-green-400 to-green-700 flex items-center justify-center text-white font-bold text-sm">
              {user?.name?.[0]?.toUpperCase() || 'F'}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-white text-sm font-medium truncate">{user?.name || 'Farmer'}</div>
              <div className="text-gray-500 text-xs truncate">{user?.location || 'India'}</div>
            </div>
            <button onClick={() => setUser(null)} className="text-gray-500 hover:text-red-400 text-xs transition-colors" title="Logout">⏻</button>
          </div>
        </div>
      </aside>
    </>
  );
}
